            self.custom_repr = (path_repr,) + tuple(custom_repr)
        else:
            self.custom_repr = (path_repr,)

        self.last_source_path = None
        self.max_variable_length = max_variable_length
        self.normalize = normalize
        self.relative_time = relative_time
